package org.mockito;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.Collection;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.hamcrest.Matcher;
import org.junit.*;
import org.junit.Test;
import org.mockito.internal.matchers.*;
import org.mockito.internal.matchers.apachecommons.ReflectionEquals;
import org.mockito.internal.progress.HandyReturnValues;
import org.mockito.internal.progress.MockingProgress;
import org.mockito.internal.progress.ThreadSafeMockingProgress;
import static org.junit.Assert.*;
import static org.junit.Assert.assertNull;
import static org.mockito.Matchers.same;

public class Matchers_same_TriageGen1Test {

    /**
     * The method 'same(T value)' in Mockito's Matchers class is a matcher factory.
     * It returns the result of reportMatcher(...).<T>returnNull().
     * In Mockito's architecture, these methods are designed to return null (or a dummy value)
     * during the stubbing phase, while they register a Matcher internally in the 
     * ArgumentMatcher stack.
     * 
     * Since the method is defined as returning T (via returnNull()), 
     * the primary behavior to verify is that it returns null and handles different types.
     */

    @Test
    public void testSameWithInteger() {
        Integer value = 10;
        Integer result = same(value);
        assertNull("The same matcher should return null during stubbing", result);
    }

    @Test
    public void testSameWithString() {
        String value = "test";
        String result = same(value);
        assertNull("The same matcher should return null during stubbing", result);
    }

    @Test
    public void testSameWithObject() {
        Object value = new Object();
        Object result = same(value);
        assertNull("The same matcher should return null during stubbing", result);
    }

    @Test
    public void testSameWithNull() {
        // Testing the edge case where the input value itself is null
        Object value = null;
        Object result = same(value);
        assertNull("The same matcher should return null even if input is null", result);
    }

    @Test
    public void testSameWithDouble() {
        Double value = 10.5;
        Double result = same(value);
        assertNull("The same matcher should return null during stubbing", result);
    }
}
